class AmConfigStore {
  services;
  characterId;
  reason;
  current;
  domainRevisions = new Map;
  queue = Promise.resolve();
  error = null;
  persistenceListeners = new Set;
  writes = 0;
  constructor(services, characterId, parts, reason = "analysis") {
    this.services = services;
    this.characterId = characterId;
    this.reason = reason;
    this.current = buildAmConfig(parts);
  }
  static async open(services, characterId, reason) {
    return new AmConfigStore(services, characterId, await loadAmConfigParts(services, characterId), reason);
  }
  getCurrentSnapshot() {
    return this.current;
  }
  update(mutate, options = {}) {
    const before = this.current;
    const after = mutate(jsonClone(before));
    if (!after || same(before, after))
      return this.current;
    this.current = after;
    for (const domain of options.domains ?? ["*"])
      this.domainRevisions.set(domain, (this.domainRevisions.get(domain) ?? 0) + 1);
    this.writes += 1;
    this.queue = this.queue.then(async () => {
      try {
        await persistAmConfigChange(this.services, this.characterId, before, after, { reason: this.reason });
      } catch (error) {
        this.error ??= error;
        this.services.log.append("error", "analysis", `Saving analysis results failed: ${error instanceof Error ? error.message : String(error)}`);
        this.persistenceListeners.forEach((l) => l());
      }
    });
    return after;
  }
  async flushSave() {
    await this.queue;
    if (this.error) {
      const error = this.error;
      this.error = null;
      throw error;
    }
  }
  async settle() {
    await this.queue;
  }
  getDomainRevision(domain) {
    return this.domainRevisions.get(domain) ?? 0;
  }
  get writeCount() {
    return this.writes;
  }
  getPersistenceSnapshot() {
    return { error: this.error ? String(this.error instanceof Error ? this.error.message : this.error) : "", pending: false };
  }
  subscribePersistence(listener) {
    this.persistenceListeners.add(listener);
    return () => this.persistenceListeners.delete(listener);
  }
}

