function imageUrlIndex(images) {
  const byKey = new Map;
  const byName = new Map;
  for (const image of images) {
    if (image.imageId)
      byKey.set(image.imageId, image);
    if (image.asset?.key)
      byKey.set(image.asset.key, image);
    if (image.asset?.name && !byName.has(image.asset.name))
      byName.set(image.asset.name, image);
  }
  return (asset) => {
    if (!asset)
      return null;
    const hit = asset.key && byKey.get(asset.key) || asset.name && byName.get(asset.name);
    return hit ? hit.thumbnailUrl || hit.url : null;
  };
}
