// src/backend/services/index.ts
function createServices(host, userId) {
  const events = createEventBus(host, userId);
  const log = createRunLog({ events, host });
  const storage = createStorageService(host, userId, { events, log });
  const loadConfig = () => storage.loadConfig();
  const imageBytes = createImageBytesService({ host, userId, storage, log });
  const llm = createLlmService({ host, userId, loadConfig, log, getJson: (url, options) => imageBytes.getJson(url, options) });
  const images = createImageService({ host, userId, loadConfig, log });
  const sources = createSourcesService({ host, userId, imageBytes, storage, log });
  return { host, userId, storage, llm, images, imageBytes, sources, events, log };
}
function createServicesRegistry(host, factory = createServices) {
  const byUser = new Map;
  const get = (userId) => {
    const key = userId ?? "";
    let services = byUser.get(key);
    if (!services)
      byUser.set(key, services = factory(host, userId));
    return services;
  };
  return {
    get,
    acceptFrontendMessage(payload, userId) {
      if (!payload || typeof payload !== "object")
        return false;
      return get(userId).imageBytes.acceptFrontendMessage(payload);
    },
    all: () => [...byUser.values()]
  };
}

// src/backend/runtime.ts
function createBackendRuntime(options) {
  const registry = createServicesRegistry(options.host, options.createServices);
  const modulesByUser = new Map;
  const modules = (userId) => {
    const key = userId ?? "";
    let current = modulesByUser.get(key);
    if (current)
      return current;
    const services = registry.get(userId);
    current = {};
    modulesByUser.set(key, current);
    const get = () => modulesByUser.get(key);
    for (const factory of options.modules)
      Object.assign(current, factory(services, get));
    return current;
  };
  const context = (userId, meta = {}) => ({
    ...registry.get(userId),
    ...meta,
    modules: modules(userId)
  });
  const router = createRouter({
    host: options.host,
    handlers: options.handlers ?? allHandlers(),
    getContext: (userId, meta) => context(userId, { clientId: meta.clientId, frontendSessionId: meta.frontendSessionId }),
    onError: (error, meta) => {
      if (error.code === "cancelled")
        return;
      registry.get(meta.userId).log.append("warn", "rpc", `${meta.method} failed: ${error.message}`, { code: error.code, detailCode: error.detailCode });
    }
  });
  return {
    registry,
    router,
    services: (userId) => registry.get(userId),
    modules,
    context,
    users: () => [...modulesByUser.keys()].map((key) => key === "" ? undefined : key),
    async handleFrontendMessage(payload, userId, frontendSessionId) {
      if (registry.acceptFrontendMessage(payload, userId))
        return true;
      return router.handleFrontendMessage(payload, userId, frontendSessionId);
    },
    dispose() {
      for (const mods of modulesByUser.values()) {
        for (const mod of Object.values(mods)) {
          try {
            mod?.dispose?.();
          } catch {}
        }
      }
      modulesByUser.clear();
    }
  };
}

// src/backend.ts
var pipelineModule = (services, getModules) => {
  const created = createPipelineModule(services, getModules);
  created.pipeline.recover().catch((error) => services.log.append("warn", "pipeline", `Recovery failed: ${errorText(error)}`));
  return created;
};
var analysisModule = (services, getModules) => createAnalysisModule(services, getModules);
var runtime2 = createBackendRuntime({ host: spindle, modules: [pipelineModule, analysisModule] });
function errorText(error) {
  return error instanceof Error ? error.message : String(error);
}
spindle.registerInterceptor(async (messages) => stripForInterceptor(messages));
function forUser(userId, run) {
  const targets = userId !== undefined ? [userId] : runtime2.users().length ? runtime2.users() : [undefined];
  for (const target of targets) {
    Promise.resolve().then(() => run(target)).catch((error) => {
      try {
        runtime2.services(target).log.append("error", "host-event", errorText(error));
      } catch {}
    });
  }
}
spindle.on("GENERATION_ENDED", (payload, userId) => {
  forUser(userId, (user) => runtime2.modules(user).pipeline.handleGenerationEnded(payload));
});
var PIPELINE_HOST_EVENTS = [
  "GENERATION_STARTED",
  "GENERATION_STOPPED",
  "MESSAGE_SWIPED",
  "MESSAGE_DELETED",
  "MESSAGE_EDITED",
  "SWIPE_EDITED",
  "CHAT_CHANGED",
  "CHAT_SWITCHED",
  "CHARACTER_EDITED",
  "CHARACTER_DELETED"
];
for (const event of PIPELINE_HOST_EVENTS) {
  spindle.on(event, (payload, userId) => {
    forUser(userId, (user) => {
      if (event === "CHARACTER_EDITED" || event === "CHARACTER_DELETED") {
        const characterId = payload?.characterId ?? payload?.id;
        runtime2.services(user).sources.invalidate(typeof characterId === "string" ? characterId : undefined);
      }
      return runtime2.modules(user).pipeline.handleHostEvent(event, payload);
    });
  });
}
spindle.onFrontendMessage(async (payload, userId, frontendSessionId) => {
  try {
    await runtime2.handleFrontendMessage(payload, userId, frontendSessionId);
  } catch (error) {
    try {
      runtime2.services(userId).log.append("error", "frontend", errorText(error));
    } catch {
      spindle.log.error(`Inlay Illustrator frontend message failed: ${errorText(error)}`);
    }
  }
});
spindle.log.info("Inlay Illustrator (Asset Maid port) loaded.");
